import{_ as r,o as d,c as o,a2 as l}from"./chunks/framework.G0y0PQA7.js";const a="/relio/shots/ko/edit-search-dialog.png",i="/relio/shots/ko/edit-edit-all.png",c=JSON.parse('{"title":"편집","description":"","frontmatter":{},"headers":[],"relativePath":"features/edit.md","filePath":"features/edit.md"}'),e={name:"features/edit.md"};function s(n,t,g,b,k,h){return d(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="편집" tabindex="-1">편집 <a class="header-anchor" href="#편집" aria-label="Permalink to &quot;편집&quot;">​</a></h1><p>되돌리기, 잘라내기·복사·붙여넣기, 삭제, 찾기와 검색 창, 모든 속성 편집처럼 편집 메뉴의 기능을 설명합니다.</p><p>그리는 순서는 빠른 시작의 <a href="/relio/quick/draw">테이블·컬럼·관계 그리기</a>에 있습니다.</p><h2 id="편집-메뉴" tabindex="-1">편집 메뉴 <a class="header-anchor" href="#편집-메뉴" aria-label="Permalink to &quot;편집 메뉴&quot;">​</a></h2><table tabindex="0"><thead><tr><th>메뉴 › 항목</th><th>단축키</th><th>하는 일</th></tr></thead><tbody><tr><td>편집 › 되돌리기</td><td><kbd>Ctrl</kbd>+<kbd>Z</kbd></td><td>마지막 편집을 되돌립니다.</td></tr><tr><td>편집 › 다시 하기</td><td><kbd>Ctrl</kbd>+<kbd>Y</kbd> 또는 <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Z</kbd></td><td>되돌린 편집을 다시 합니다.</td></tr><tr><td>편집 › 잘라내기</td><td><kbd>Ctrl</kbd>+<kbd>X</kbd></td><td>고른 것을 복사하고 지웁니다.</td></tr><tr><td>편집 › 복사</td><td><kbd>Ctrl</kbd>+<kbd>C</kbd></td><td>선택한 노드나 컬럼을 복사합니다.</td></tr><tr><td>편집 › 붙여넣기</td><td><kbd>Ctrl</kbd>+<kbd>V</kbd></td><td>복사한 것을 붙여 넣습니다. 붙여 넣을 내용이 있을 때만 쓸 수 있습니다.</td></tr><tr><td>편집 › 삭제</td><td><kbd>Delete</kbd></td><td>고른 것을 지웁니다.</td></tr><tr><td>편집 › 모두 선택</td><td><kbd>Ctrl</kbd>+<kbd>A</kbd></td><td>지금 화면의 노드를 모두 고릅니다.</td></tr><tr><td>편집 › 찾기</td><td><kbd>Ctrl</kbd>+<kbd>F</kbd></td><td>캔버스 위 찾기 막대를 엽니다. <a href="/relio/features/find">찾기와 강조</a></td></tr><tr><td>편집 › 검색…</td><td><kbd>Ctrl</kbd>+<kbd>H</kbd></td><td>검색 창을 엽니다. 아래 &quot;검색 창&quot;을 보세요.</td></tr><tr><td>편집 › 모든 속성 편집…</td><td></td><td>여러 테이블의 컬럼 속성을 표 하나에서 고칩니다.</td></tr></tbody></table><p>쓸 수 없는 항목은 자리를 지킨 채 흐리게 보이고, 마우스를 올리면 이유(예: &quot;노드나 컬럼을 고르면 사용&quot;)가 나옵니다.</p><h2 id="되돌리기" tabindex="-1">되돌리기 <a class="header-anchor" href="#되돌리기" aria-label="Permalink to &quot;되돌리기&quot;">​</a></h2><p>모든 편집은 되돌릴 수 있습니다. 보기 메뉴의 표시 설정을 바꾼 것, DB·다른 형식에서 가져온 것, 합치기를 적용한 것도 되돌리기 한 번으로 통째로 돌아갑니다. 카테고리 탭을 바꾸거나 설계 검사 예외를 두는 것처럼 문서를 바꾸지 않는 일은 되돌리기 대상이 아닙니다.</p><h2 id="잘라내기·복사·붙여넣기" tabindex="-1">잘라내기·복사·붙여넣기 <a class="header-anchor" href="#잘라내기·복사·붙여넣기" aria-label="Permalink to &quot;잘라내기·복사·붙여넣기&quot;">​</a></h2><ul><li><strong>노드</strong> — 테이블·뷰·노트·이미지·카테고리를 복사합니다. 붙여 넣으면 마우스 위치에 놓이고, 같은 내용을 거듭 붙이면 조금씩 비켜 놓습니다. 복사한 노드끼리 이은 관계선도 함께 옵니다.</li><li><strong>다른 문서로</strong> — 다른 탭의 문서에도 붙일 수 있습니다. 다른 문서에서 온 그룹 컬럼은 그 문서의 그룹에 더해집니다.</li><li><strong>카테고리 화면에서</strong> — 붙여 넣은 노드는 그 카테고리(여러 개를 함께 보는 중이면 주 카테고리)에 들어갑니다. 카테고리를 붙일 때 이름이 겹치면 번호를 붙입니다.</li><li><strong>컬럼</strong> — 캔버스에서 테이블 안 컬럼을 하나 이상 고르고 복사한 뒤, 다른 테이블을 고르고 붙여 넣으면 그 테이블 끝에 컬럼으로 붙습니다. 기본 키(PK)·NOT NULL 같은 속성은 함께 오고 외래 키(FK) 관계는 오지 않습니다. 테이블을 고르지 않았으면 &quot;컬럼을 붙여 넣을 테이블을 하나 선택하세요.&quot;라고 알립니다.</li></ul><h2 id="삭제" tabindex="-1">삭제 <a class="header-anchor" href="#삭제" aria-label="Permalink to &quot;삭제&quot;">​</a></h2><ul><li>관계를 지우면 &quot;FK로 쓰던 컬럼도 함께 지울까요?&quot;를 묻습니다. <strong>예</strong>는 FK 컬럼도 지우고, <strong>아니요</strong>는 일반 컬럼으로 남깁니다.</li><li>캔버스에서 컬럼을 고르고 <kbd>Delete</kbd>를 누르면 그 컬럼을 지웁니다. FK 컬럼과 다른 테이블이 참조하는 컬럼은 지울 수 없다고 알립니다.</li><li>컬럼을 지우면 그 컬럼을 쓰던 인덱스·복합 고유 키·테스트 데이터에서도 빠집니다. 그런 곳이 있으면 목록을 보여 주고 계속할지 묻습니다.</li></ul><h2 id="검색-창" tabindex="-1">검색 창 <a class="header-anchor" href="#검색-창" aria-label="Permalink to &quot;검색 창&quot;">​</a></h2><p>편집 › 검색…(<kbd>Ctrl</kbd>+<kbd>H</kbd>)은 모델 전체에서 글자를 찾고 한꺼번에 바꾸는 창입니다. 찾기 막대 오른쪽의 <strong>…</strong> 단추(마우스를 올리면 &quot;찾기·바꾸기…&quot;)도 같은 검색 창을 엽니다.</p><ul><li><strong>검색 문자열</strong> — 찾을 이름·글자.</li><li><strong>바꿀 문자열</strong> — 새 글자. 비우면 찾은 글자를 지웁니다.</li><li><strong>대소문자 구분</strong> · <strong>정규식</strong> — 찾는 방식을 정합니다.</li><li><strong>범위</strong> 탭 — 찾을 곳을 체크합니다. <ul><li>모두</li><li>단어 (물리명·논리명·형식·길이·소수·설명)</li><li>테이블 (물리명·논리명·그룹명·컬럼 이름·형식·길이·소수·기본값·설명)</li><li>그룹 (그룹명·컬럼 이름·형식·길이·소수·기본값·설명)</li><li>모델의 특성 · 인덱스 · 관계 · 노트</li></ul></li><li><strong>결과</strong> 탭 — 찾은 곳의 위치와 칸이 표로 나옵니다. 행을 누르면 캔버스에서 그 객체를 고릅니다.</li><li>단추 <strong>모두 검색</strong> · <strong>찾기</strong> · <strong>대체</strong><ul><li><strong>모두 검색</strong>은 범위 안의 모든 결과를 새로 찾아 결과 탭에 모으고, 캔버스에도 강조합니다. 창에 <strong>Enter</strong>를 눌러도 같습니다.</li><li><strong>찾기</strong>는 결과 탭의 결과를 하나씩 차례로 골라 캔버스에서 그 객체를 선택합니다. 마지막 다음에는 처음으로 돌아갑니다. 아직 찾은 결과가 없으면 먼저 검색한 뒤 첫 결과로 갑니다.</li><li><strong>대체</strong>는 결과 탭에서 체크한 것만 바꿉니다. 바꾸기는 되돌리기 한 번으로 돌아갑니다.</li></ul></li></ul><p>단어 값(컬럼 이름·형식 등)을 바꾸면 그 단어를 쓰는 모든 컬럼이 함께 바뀝니다. 바꾼 뒤 상태 표시줄에 함께 바뀐 컬럼 수가 나옵니다.</p><figure class="shot" data-scene="edit-search-dialog"><img src="'+a+'" alt="검색 창 — 범위 탭에서 찾을 곳을 고르는 모습" loading="lazy"><figcaption>검색 창 — 범위 탭에서 찾을 곳을 고르는 모습</figcaption></figure><h2 id="모든-속성-편집" tabindex="-1">모든 속성 편집 <a class="header-anchor" href="#모든-속성-편집" aria-label="Permalink to &quot;모든 속성 편집&quot;">​</a></h2><p>편집 › 모든 속성 편집…은 모든 테이블의 컬럼을 표 하나로 보여 줍니다.</p><ul><li>열: 컬럼 논리명 · 컬럼 물리명 · 테이블 논리명 · 테이블 물리명 · 단어 · 형식 · 길이 · 소수 · PK · FK · NOT NULL · UNIQUE.</li><li>머리글을 누르면 정렬하고, <strong>걸러 보기 (이름)</strong> 칸으로 원하는 행만 봅니다.</li><li>Excel에서 복사한 여러 칸을 표에 붙여 넣을 수 있습니다.</li><li>테이블 이름 칸을 고치면 그 테이블의 모든 행에 반영됩니다. 단어를 고치면 같은 단어를 쓰는 컬럼도 바뀝니다.</li><li>고친 행 수가 &quot;바뀐 행 n개&quot;로 보이고, <strong>확인</strong>을 누르면 한 번에 적용합니다(되돌리기 한 번).</li></ul><figure class="shot" data-scene="edit-edit-all"><img src="'+i+'" alt="모든 속성 편집 창 — 여러 테이블의 컬럼을 한 표에서 고치는 모습" loading="lazy"><figcaption>모든 속성 편집 창 — 여러 테이블의 컬럼을 한 표에서 고치는 모습</figcaption></figure><h2 id="오른쪽-클릭-메뉴" tabindex="-1">오른쪽 클릭 메뉴 <a class="header-anchor" href="#오른쪽-클릭-메뉴" aria-label="Permalink to &quot;오른쪽 클릭 메뉴&quot;">​</a></h2><p>캔버스에서 오른쪽 클릭하면 그 자리에 맞는 짧은 메뉴가 나옵니다.</p><ul><li><strong>노드·연결선 위</strong> — 정보…(<kbd>Enter</kbd>), 크기 자동 조정·직각 연결선·기본값 복원·연결선 정리, 배경색, 글꼴·글꼴 크기, 여러 개를 골랐으면 배치 ▸, 잘라내기·복사·붙여넣기·삭제, 그리고 <strong>문서 ▸</strong>. 설계 검사 지적이 있으면 맨 아래에 **지적 (n) ▸**이 붙습니다.</li><li><strong>테이블·뷰 하나 위</strong> — 정보… 바로 아래에 <strong>AI용 위치 복사</strong>가 있습니다. <code>&quot;…\\shop.erm&quot;의 ORDERS 테이블</code> 같은 한 줄을 복사해 AI 도구에 붙여 넣습니다(저장된 파일에서만, 아웃라인 목록의 오른쪽 클릭에도 있음). <a href="/relio/features/ai#파일·위치-넘겨주기">AI와 함께 쓰기 › 파일·위치 넘겨주기</a></li><li><strong>빈 캔버스</strong> — 테이블 추가(<kbd>T</kbd>) · 노트 추가(<kbd>N</kbd>), 붙여넣기 · 모두 선택, 되돌리기 · 다시 하기, 전체 맞춤, <strong>문서 ▸</strong>.</li><li><strong>문서 ▸</strong> — 모든 속성 편집…, 검색…, 표시 ▸, 가져오기 ▸, 내보내기 ▸, 페이지 설정…, 인쇄…, 변경 내역…, 번역 관리…, 테스트 데이터…, 카테고리 ▸, 그룹 관리…, 글로벌 그룹 관리…, 단어 사전…, 트리거·시퀀스·테이블스페이스 추가…, 옵션…, 모델 특성…처럼 문서 전체에 쓰는 명령이 모여 있습니다.</li></ul><p>도구 › 환경 설정 › 일반의 <strong>도구 막대</strong>를 **ERMaster식 (원래 전부)**로 바꾸면, 도구 막대 단추와 오른쪽 클릭 메뉴가 ERMaster의 원래 구성을 따릅니다. 메뉴 막대는 같습니다.</p>',25)])])}const p=r(e,[["render",s]]);export{c as __pageData,p as default};
